"""Host-owned, versioned acceptance domains. Never generated by the candidate.

These are explicit product contracts, not an oracle for arbitrary user goals.
Only finite JSON inputs are accepted; no personal data, IO or model is needed.
"""
import copy
from .. import policy
from .catalog import encoded, fail

DOMAINS = {
    'clean-lines': {
        'name': '清理重复清单',
        'contract': '输入为字符串列表。每项去除首尾空白，丢弃空项，按首次出现顺序去重（区分大小写），用换行连接；空表返回空字符串。',
        'inputs': [[], [' A ', 'A', '', 'B'], ['a', 'A', 'a'], ['  ', '\t', '中文'],
                   ['旅行', ' 旅行 ', '机票', '酒店'], ['milk', 'Milk', '', 'milk'],
                   ['书', '笔', '书', '纸'], [' Alice ', 'Bob', 'Alice', 'Eve'],
                   ['任务甲', '任务乙', '\n任务甲\n'], ['x', ' x ', '\tY', 'z', 'Y']],
    },
    'group-counts': {
        'name': '分类数量汇总',
        'contract': '输入为包含 group（非空字符串）和 count（非负整数）的对象列表。按 group 精确相等分组、累加 count，保留组首次出现顺序；每行输出 group:count，无空格；空表为空字符串。不用于金额或浮点数。',
        'inputs': [[], [{'group': '书', 'count': 2}, {'group': '书', 'count': 3}],
                   [{'group': 'B', 'count': 0}, {'group': 'A', 'count': 1}],
                   [{'group': '笔', 'count': 4}, {'group': '纸', 'count': 7}, {'group': '笔', 'count': 1}],
                   [{'group': '工作', 'count': 5}, {'group': '生活', 'count': 3}, {'group': '工作', 'count': 6}],
                   [{'group': '电影', 'count': 2}, {'group': '书籍', 'count': 8}],
                   [{'group': '早餐', 'count': 0}, {'group': '午餐', 'count': 3}],
                   [{'group': 'Z', 'count': 3}, {'group': 'a', 'count': 4}, {'group': 'Z', 'count': 8}],
                   [{'group': '邮件', 'count': 12}, {'group': '会议', 'count': 2}],
                   [{'group': '红', 'count': 9}, {'group': '蓝', 'count': 1}, {'group': '红', 'count': 0}]],
    },
    'byte-total': {
        'name': '文件大小汇总',
        'contract': '输入为包含 size（非负整数）和 unit 的对象列表。unit 只允许 B、KiB、MiB，分别乘 1、1024、1048576 后求和；返回十进制总字节数字符串，空表返回 0。不处理 KB/MB 或小数，也不扫描磁盘。',
        'inputs': [[], [{'size': 2, 'unit': 'KiB'}, {'size': 3, 'unit': 'B'}],
                   [{'size': 1, 'unit': 'MiB'}, {'size': 1, 'unit': 'KiB'}],
                   [{'size': 0, 'unit': 'MiB'}],
                   [{'size': 7, 'unit': 'KiB'}, {'size': 9, 'unit': 'B'}],
                   [{'size': 3, 'unit': 'MiB'}, {'size': 2, 'unit': 'KiB'}],
                   [{'size': 55, 'unit': 'B'}, {'size': 11, 'unit': 'B'}],
                   [{'size': 8, 'unit': 'KiB'}],
                   [{'size': 2, 'unit': 'MiB'}, {'size': 21, 'unit': 'B'}],
                   [{'size': 17, 'unit': 'KiB'}, {'size': 90, 'unit': 'B'}]],
    },
}


def expected(domain, value):
    encoded(value)
    if not isinstance(domain, str) or domain not in DOMAINS or not isinstance(value, list) or len(value) > 100:
        fail('任务域或输入不明确，请选择受支持的契约；没有自动推断业务含义。', 'growth_domain_invalid')
    if domain == 'clean-lines':
        if any(not isinstance(s, str) or len(s) > 256 for s in value):
            fail('清单只接受短字符串。', 'growth_domain_invalid')
        return '\n'.join(dict.fromkeys(s.strip() for s in value if s.strip()))
    if domain == 'group-counts':
        if any(not isinstance(x, dict) or set(x) != {'group', 'count'}
               or not isinstance(x['group'], str) or not 1 <= len(x['group']) <= 80
               or any(c in x['group'] for c in '\r\n:')
               or type(x['count']) is not int or not 0 <= x['count'] <= 1000000 for x in value):
            fail('分组统计需要明确组名及非负整数数量。', 'growth_domain_invalid')
        groups = list(dict.fromkeys(x['group'] for x in value))
        return '\n'.join(g + ':' + str(sum(x['count'] for x in value if x['group'] == g)) for g in groups)
    units = {'B': 1, 'KiB': 1024, 'MiB': 1048576}
    if any(not isinstance(x, dict) or set(x) != {'size', 'unit'} or not isinstance(x['unit'], str)
           or x['unit'] not in units or type(x['size']) is not int or not 0 <= x['size'] <= 1000000 for x in value):
        fail('大小单位或精度不明确；请使用整数 B、KiB、MiB。', 'growth_domain_invalid')
    return str(sum(x['size'] * units[x['unit']] for x in value))


def specification(domain):
    if not isinstance(domain, str) or domain not in DOMAINS: fail('请先明确选择任务契约。', 'growth_domain_invalid')
    spec = copy.deepcopy(DOMAINS[domain])
    cases = [{'input': x, 'expected': expected(domain, x)} for x in spec.pop('inputs')]
    value = {'id': domain, 'version': 1, **spec, 'public': cases[:2], 'heldout': cases[2:4],
             'samples': cases[4:], 'oracle_source': 'host-authored explicit contract v1',
             'criterion': 'exact output equality; no claim of arbitrary semantic correctness'}
    return {**value, 'digest': policy.digest(policy.canonical_json(value).encode())}


def listing():
    return [{'id': k, 'name': v['name'], 'contract': v['contract']} for k, v in DOMAINS.items()]
